  return RESUME_IDS.find((id) => !used.has(id)) ?? null;
}

// Чего нет в resume.<id>, у r2–r5 нейтрально, а не как по умолчанию у ключа: умолчания ключей — настройки
// фронтенд-владельца (слова поиска, стоп-слова, спорные случаи), другой профессии они не подходят
const RESUME_NEUTRAL = {
  resume: '',
  extra: '',
  facts: {},
  about: [],
  preset: 'generic',
  rules: {},
  cases: [],
  roles: [],
  in_name: [],
  anywhere: [],
  formats: ['REMOTE'],
  area: null,
  education: ['not_required_or_not_specified'],
  stop_words: [],
  rules_off: ['lead'],
  examples: '',
  prompt: {},
};

// Есть ли у резюме слова для поиска: без них искать нечего (по роли одной — сотни чужих вакансий)
const resumeSearchable = (rs) => rs['search.anywhere'].length + rs['search.in_name'].length > 0;

// Данные резюме из настроек (то, что у r2–r5 лежит в resume.<id>): для клонирования и записи
function resumeData(s) {
  return Object.fromEntries(Object.entries(RESUME_FIELDS).map(([field, key]) => [field, s[key]]));
}

// Настройки для резюме id: основное и неизвестное (удалённое, без данных) — сами s, остальные — копия s
// с подменёнными полями (чего нет в resume.<id> — нейтральное значение RESUME_NEUTRAL)
function resumeSettings(s, id) {
  if (!id || id === 'r1') return s;
  const data = s[`resume.${id}`];
  if (!data || !resumeById(s, id)) return s;
  const out = { ...s };
  for (const [field, key] of Object.entries(RESUME_FIELDS)) {
    out[key] = field in data ? data[field] : RESUME_NEUTRAL[field];
  }
  return out;
}

// Что записать в settings, чтобы поменять поля резюме id: { имя ключа: значение }.
// r1 — глобальные ключи, r2–r5 — один ключ resume.<id> с дописанными полями
function resumeRows(s, id, patch) {
  if (!id || id === 'r1') {
    return Object.fromEntries(Object.entries(patch).map(([field, value]) => [RESUME_FIELDS[field], value]));
  }
  return { [`resume.${id}`]: { ...(s[`resume.${id}`] ?? {}), ...patch } };
}

const claimed = $('Claim').all().map((i) => i.json);
const allSettings = loadSettings($('Settings').all());
// Тело функции — без отступа: многострочные шаблонные строки промпта нельзя сдвигать, иначе изменится текст
// промпта и prompt_v
function buildFor(settings, rows) {
const resume = resumeText(settings);
if (!resume) throw new Error('Пустое резюме: пришли PDF боту или импортируй профиль (docs/onboarding.md)');

const frontend = settings['profile.preset'] === 'frontend';
const facts = settings['profile.facts'];
const provider = settings['llm.provider'];
const model = provider === 'claude' ? $env.CLAUDE_MODEL || 'claude-haiku-4-5' : $env.GEMINI_MODEL || 'gemini-3.5-flash-lite';

// Поправки кандидата из настроек бота (⚙️ → 🤖 Нейросеть → ✏️ Спорные случаи, список «случай: решение»).
// frontend: встроенный случай с другим решением — поправка с его формулировкой; встроенного нет в списке — «особого
// правила нет»; случай пользователя — поправка как есть. Список по умолчанию — поправок нет, промпт прежний.
// generic: встроенных случаев нет — каждая запись списка — поправка
const cases = settings['llm.cases'];
const builtinCase = (key) => (frontend ? cases.find((c) => builtinOf(c.case) === key) : undefined);
function overrides() {
  const lines = [];
  if (frontend) {
    for (const [key, b] of Object.entries(BUILTIN_CASES)) {
      const entry = builtinCase(key);
      if (!entry) lines.push(`- ${b.prompt} — особого правила нет, решай по общим правилам;`);
      else if (entry.decision !== b.default) lines.push(`- ${b.prompt} — ${entry.decision};`);
    }
  }
  // Записи, которые не стали встроенным случаем: второе «vue» и т. п. — тоже поправки
  const used = new Set(Object.keys(BUILTIN_CASES).map(builtinCase).filter(Boolean));
  for (const c of cases) if (!used.has(c)) lines.push(`- ${c.case} — ${c.decision};`);
  return lines.length
    ? `\n\nПоправки кандидата — важнее правил выше, если противоречат им; остальные причины для skip и maybe действуют:\n${lines.join('\n')}`
    : '';
}
const aiCase = builtinCase('ai_js');

// Правила пресета frontend — откалиброваны на вакансиях владельца, менять только вместе с теневым режимом
const FRONTEND_RULES = `skip, если:
- основной стек не React и не Vue: Angular, Svelte, только вёрстка, чистый бэкенд, QA и т. п. React «будет плюсом» при таком стеке — тоже skip. Не skip, если вакансия про разработку на AI (интеграции LLM, AI-агенты, в том числе голосовые, RAG) на JS/TS (Node.js, NestJS, TypeScript): она apply, даже если это бэкенд;
- разработка на AI, где основной язык не JS/TS: Python, Go, Java и т. п. Fullstack с обязательным React — по правилу fullstack (maybe);
- ML и Data Science: обучение моделей, MLOps, исследования, разметка данных — без разработки продукта на готовых LLM;
- мобильная разработка — основная работа: React Native, Flutter, Swift, Kotlin. React Native или Electron как дополнительная задача при веб-React — не skip;
- нужен английский C1 и выше или вся коммуникация в команде только на английском;
- прямо написано, что нужно жить в определённой стране или регионе (РФ, Казахстан, Беларусь, Узбекистан, Европа…), быть её налоговым резидентом или приезжать в офис, даже изредка;
- прямо написано, что работать нужно ночью по времени ${facts.country_gen || 'кандидата'}, например в часы США (EST, PST). Компания из США или Европы без требований к часам работы — не skip.

maybe, если:
- основной стек — Vue (Vue.js, Nuxt), а React нет в обязательных требованиях: кандидат готов работать на Vue, решает сам;
- fullstack: в обязательных требованиях и React, и бэкенд на любом языке (Node.js, .NET, Java, Python, Go, PHP…) — даже если бэкенда много. Кроме разработки на AI — она apply;
- нужен английский B2;
- есть мягкий или косвенный признак привязки к стране или офису — даже если всё остальное подходит: «желательно», «будет плюсом», «предпочтительно»; льготы для жителей РФ (ИТ-ипотека, отсрочка, бронь от мобилизации); трудоустройство по трудовому кодексу другой страны (ТК РУз, ТК РК…);
- в тексте слишком мало данных, чтобы решить.

apply, если React или Next.js — основной стек (в том числе вместе с Vue: «React, Vue», «React или Vue»), работа удалённая без привязки к стране и нет причин для skip или maybe.

apply и тогда, когда вакансия про разработку на AI на JS/TS (Node.js, NestJS, TypeScript, в том числе бэкенд без React): интеграции LLM и нейросетей в продукт, AI-агенты, RAG или AI-first / AI-native разработка, где работа с AI — главное в роли. Fullstack на JS/TS здесь не maybe. Остальные причины для skip и maybe действуют: мобильная разработка, английский, страна или офис, ночные часы. AI на Python, Go, Java и т. п. — skip (кандидат пишет на JS/TS). Если AI упомянут мимоходом («используем ChatGPT», «Copilot приветствуется»), это не разработка на AI — решай по стеку.

На решение не влияют:
- уровень Middle или Senior и требуемый опыт (Middle и «более 6 лет» — тоже apply);
- зарплата и её отсутствие;
- форма оформления: ТК, ГПХ, ИП, самозанятость;
- график по московскому времени, в том числе строгий с 9 до 18 МСК;
- сфера бизнеса;
- тестовое задание;
- нехватка у кандидата опыта в бэкенде или других технологиях вакансии: если в обязательных требованиях есть React, это не skip (fullstack — maybe).

Города, где вакансия размещена на hh, — не требование к месту жительства.`;

// Правила пресета generic — из резюме (онбординг W11): разделы llm.rules, строки списком
function genericRules(r) {
  const list = (title, lines) => (lines?.length ? `${title}\n${lines.map((l) => `- ${l}`).join('\n')}` : '');
  return [
    list('skip, если:', r.skip),
    list('maybe, если:', r.maybe),
    list('apply, если:', r.apply),
    list('На решение не влияют:', r.ignore),
    ...(r.notes ?? []),
  ]
    .filter(Boolean)
    .join('\n\n');
}

const about = settings['profile.about'];
const SYSTEM = [
  `Ты отбираешь вакансии с hh.ru для ${frontend ? 'кандидата-фронтендера' : 'кандидата'}. По вакансии реши, стоит ли откликаться:
- apply — подходит, откликаться;
- maybe — спорно, кандидат решит сам;
- skip — не подходит.`,
  about.length && `О кандидате (подробно — в резюме ниже):\n${about.map((line) => `- ${line}`).join('\n')}`,
