  ]
    .filter(Boolean)
    .join('\n');

// reason идёт первым: модель сначала формулирует причину, потом решение
const REASON = 'Главная причина решения, одна фраза до 150 символов';
const DECISIONS = ['apply', 'maybe', 'skip'];

function body(r) {
  const text = vacancyText(r);
