}

const s = loadSettings($('Settings').all());
if (!s['profile.first_quiet']) return [];
const now = new Date().toISOString();
return $('Parse verdict')
  .all()
  .map((i) => i.json)
  .filter((r) => r.outcome === 'scored' && (s['llm.shadow'] || r.decision !== 'skip'))
