  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.id);
if (!rows.length) return [];

const hits = rows.reduce((n, r) => n + (Number(r.hits) || 1), 0);
const first = Math.min(...rows.map((r) => Date.parse(r.first_at) || Date.now()));
const last = Math.max(...rows.map((r) => Date.parse(r.last_at) || Date.now()));
const span = localHM(first) === localHM(last) ? localHM(first) : `${localHM(first)}–${localHM(last)}`;
return [{ json: { text: `✅ <b>${esc(rows[0].workflow)}</b> снова работает: ошибок было ${hits} (${span} по местному)` } }];

// W2 · Release — вернуть в detailed захваченные строки, по которым карточка не ушла (07.10.2026).
// Нода: Code, режим «Run Once for All Items». Своя ветка от триггера, самая нижняя: выполняется последней.
// «Claim» перевёл строки detailed → scoring, чтобы второй запуск W2 не взял их же. Карточка ушла → «Save cards»
// поставил waiting; не ушла (лимит нейросети, сетевая ошибка, Telegram не принял) → строку надо вернуть,
// иначе она застрянет в scoring (такие W6 всё равно вернёт через 30 мин).
// Выход: [{ id }] → «Save release» (status = detailed).

const all = (name) => {
  try {
    return $(name)
      .all()
      .map((i) => i.json);
  } catch {
    return []; // нода в этом запуске не выполнялась
  }
};
// Карточка ушла или skip закрыт без карточки (теневой режим выключен)
const carded = new Set([...all('Card sent'), ...all('Quiet skips'), ...all('First save')].map((r) => r.id));
return all('Claim')
  .map((r) => r.id)
  .filter((id) => id && !carded.has(id))
  .map((id) => ({ json: { id } }));

// W2 · Run stats — сколько карточек отправил этот запуск → журнал сборов runs (запись W1 «Start run»).
// Нода: Code, режим «Run Once for All Items». Своя ветка от триггера, ниже «Summary»: выполняется последней.
// Вход: $input — item триггера: от W1 { runId, … }, у ручного запуска runId нет;
//       «Send card» — ответы Telegram (выполняется, только если были вакансии на оценку).
// Выход: [{ id, cards }] → «Save run stats» или [] — ручной запуск W2, сбора не было.

const runId = $input.first()?.json?.runId;
if (!runId) return [];

let cards = 0;
try {
  cards = $('Send card')
    .all()
    .filter((i) => i.json.result?.message_id).length;
} catch {
  // карточек в этом запуске не было — нода не выполнялась
}
return [{ json: { id: runId, cards } }];
